L-qfNTs","source":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20B%C3%B9i%20M%C3%B4n%2073%2F3C%20Qu%E1%BB%91c%20l%E1%BB%99%2022%2C%20%E1%BA%A4p%2019%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJ4R9CWm4qdTERyp--L-qfNTs","maps":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20B%C3%B9i%20M%C3%B4n%2073%2F3C%20Qu%E1%BB%91c%20l%E1%BB%99%2022%2C%20%E1%BA%A4p%2019%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJ4R9CWm4qdTERyp--L-qfNTs","key":"gmaps:ChIJ4R9CWm4qdTERyp--L-qfNTs","address_new":"73/3C Quốc lộ 22, Ấp 19, xã Xuân Thới Sơn, TP. Hồ Chí Minh","address_old":"73/3C Quốc lộ 22, Ấp 19, Huyện Hóc Môn cũ, TP.HCM cũ"},{"name":"Nhà sách Anh Đào","street":"27A Nguyễn Văn Bứa","ward":"Xuân Thới Sơn","district":"Huyện Hóc Môn","category":"nha_sach","phone":"0938660962","place":"ChIJc3t74WQrdTERxC9oAiNe7PI","source":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Anh%20%C4%90%C3%A0o%2027A%20Nguy%E1%BB%85n%20V%C4%83n%20B%E1%BB%A9a%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJc3t74WQrdTERxC9oAiNe7PI","maps":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Anh%20%C4%90%C3%A0o%2027A%20Nguy%E1%BB%85n%20V%C4%83n%20B%E1%BB%A9a%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJc3t74WQrdTERxC9oAiNe7PI","key":"gmaps:ChIJc3t74WQrdTERxC9oAiNe7PI","address_new":"27A Nguyễn Văn Bứa, xã Xuân Thới Sơn, TP. Hồ Chí Minh","address_old":"27A Nguyễn Văn Bứa, Huyện Hóc Môn cũ, TP.HCM cũ"},{"name":"Hiệu sách Quỳnh Trang","street":"1623 Lê Quang Đạo, Ấp 66","ward":"Xuân Thới Sơn","district":"Huyện Hóc Môn","category":"nha_sach","phone":"0932678110","place":"ChIJTXNqnnfVdDERTrBDw1OiDaI","source":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Qu%E1%BB%B3nh%20Trang%201623%20L%C3%AA%20Quang%20%C4%90%E1%BA%A1o%2C%20%E1%BA%A4p%2066%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJTXNqnnfVdDERTrBDw1OiDaI","maps":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Qu%E1%BB%B3nh%20Trang%201623%20L%C3%AA%20Quang%20%C4%90%E1%BA%A1o%2C%20%E1%BA%A4p%2066%20TP%20Ho%20Chi%20Minh%20Viet%20Nam&query_place_id=ChIJTXNqnnfVdDERTrBDw1OiDaI","key":"gmaps:ChIJTXNqnnfVdDERTrBDw1OiDaI","address_new":"1623 Lê Quang Đạo, Ấp 66, xã Xuân Thới Sơn, TP. Hồ Chí Minh","address_old":"1623 Lê Quang Đạo, Ấp 66, Huyện Hóc Môn cũ, TP.HCM cũ"}]'::jsonb) AS s(name text,street text,ward text,district text,category text,phone text,place text,source text,maps text,key text,address_new text,address_old text)
  WHERE s.category IN ('nha_sach','van_phong_pham')
    AND s.source LIKE 'https://%'
    AND (s.place IS NULL OR s.place ~ '^ChIJ[A-Za-z0-9_-]{20,}$')
    AND (s.maps IS NULL OR s.maps LIKE 'https://www.google.com/maps/%')
    AND s.address_new LIKE '% '||s.ward||', TP. Hồ Chí Minh'
    AND (s.phone IS NULL OR s.phone ~ '^[0-9]{8,11}$')
    AND EXISTS (SELECT 1 FROM public.sales_hcm_old_wards w
                WHERE w.province='TP Hồ Chí Minh' AND w.ward_new=s.ward AND w.legacy_district=s.district AND w.active)
    AND NOT EXISTS (SELECT 1 FROM public.field_prospects p
      WHERE p.research_source_key=s.key
      OR (s.place IS NOT NULL AND p.google_place_id=s.place)
      OR lower(btrim(p.address_line))=lower(btrim(s.address_new))
      OR (p.province='TP Hồ Chí Minh' AND p.ward_new=s.ward AND lower(btrim(p.name))=lower(btrim(s.name)))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone))
    AND NOT EXISTS (SELECT 1 FROM public.customers c
      WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new))
      OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name)))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))
), inserted AS (
  INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,address_legacy,
  category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch,google_maps_url,google_place_id)
  SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_new,
  'TP Hồ Chí Minh',s.district,s.ward,s.address_old,s.category,s.phone,NULL,
  'Nguồn công khai tra cứu 22/11/2026; CHƯA GHÉ / CHƯA XÁC MINH hoạt động, bảng hiệu và GPS thực địa. Không coi Google Maps là bằng chứng Sales ghé thăm. Nguồn: '||s.source,
  'new','manual',s.key,s.source,'2026-11-22-hcm-old-phase3-183',s.maps,s.place
  FROM vetted s
  ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
  RETURNING district,ward_new,name,category,phone,google_place_id
)
SELECT district,ward_new,name,category,phone,google_place_id FROM inserted ORDER BY district,ward_new,name;